<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api}from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),total=ref(0),page=ref(1),dialog=ref(false),form=reactive<any>({username:'',password:'',displayName:'',role:'STUDENT'});async function load(){const r:any=await api.users({page:page.value,size:10});rows.value=r.records;total.value=r.total}function open(){Object.assign(form,{username:'',password:'',displayName:'',role:'STUDENT'});dialog.value=true}async function save(){await api.createUser(form);ElMessage.success('用户创建成功');dialog.value=false;load()}async function toggle(u:any){await api.setUserStatus(u.id,u.status?0:1);load()}onMounted(load);</script>
<template><div class="page"><div class="page-header"><div><h2 class="page-title">用户管理</h2><p class="muted">维护管理员、教师和考生账号</p></div><el-button type="primary" @click="open">新增用户</el-button></div><div class="content-card"><el-table :data="rows"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="username" label="用户名"/><el-table-column prop="displayName" label="姓名"/><el-table-column prop="role" label="角色"/><el-table-column prop="status" label="状态"><template #default="s"><el-tag :type="s.row.status?'success':'info'">{{s.row.status?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="toggle(s.row)">{{s.row.status?'禁用':'启用'}}</el-button></template></el-table-column></el-table><el-pagination style="margin-top:16px;justify-content:flex-end" v-model:current-page="page" :total="total" :page-size="10" @current-change="load"/></div><el-dialog v-model="dialog" title="创建用户" width="480px"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="显示名称"><el-input v-model="form.displayName"/></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option label="考生" value="STUDENT"/><el-option label="教师" value="TEACHER"/><el-option label="管理员" value="ADMIN"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">创建</el-button></template></el-dialog></div></template>
